    private void jBtnAvaliarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jBtnAvaliarActionPerformed
        limparQuadrante();

        int x = Integer.parseInt(EixoX.getText());
        int y = Integer.parseInt(EixoY.getText());

        Ponto ponto = new Ponto(x, y);

        switch (ponto.identificarQuadrante()) {
            case PRIMEIRO:
                quadrante1.setSelected(true);
                break;

            case SEGUNDO:
                quadrante2.setSelected(true);
                break;

            case TERCEIRO:
                quadrante3.setSelected(true);
                break;

            case QUARTO:
                quadrante4.setSelected(true);
                break;

            default:
                if (ponto.estaIndicadoSobreX()) {
                    incideEixoX.setSelected(true);
                }
                if (ponto.estaIndicadoSobreY()) {
                    incideEixoY.setSelected(true);
                }

        }
    }//GEN-LAST:event_jBtnAvaliarActionPerformed
    public void limparQuadrante() {
        quadrante1.setSelected(false);
        quadrante2.setSelected(false);
        quadrante3.setSelected(false);
        quadrante4.setSelected(false);
        incideEixoX.setSelected(false);
        incideEixoY.setSelected(false);
    }

